SELECT
    note
FROM mod_cancer_note_summary
WHERE template_name = #{templateName}
  AND module = #{module}
  AND cancer = #{cancer}
  AND note is not null
  AND note != ''
  AND deleted = 1

SELECT
    title
FROM mod_cancer_note_summary
WHERE template_name = #{templateName}
  AND module = #{module}
  AND cancer = #{cancer}
  AND title is not null
  AND title != ''
  AND deleted = 1

SELECT b.references FROM references_product_map a JOIN mod_references b ON a.references_id = b.id WHERE a.product_name = #{productName}
AND a.references_name = #{module}
AND b.deleted = 1

SELECT
    note
FROM mod_common_note
WHERE module = #{module}

    AND type = #{type}


    AND type = '通用'


    AND sample_type = #{sampleType}

AND deleted = 1
